import tls from 'node:tls';
import https from 'node:https';
import fs from 'node:fs';

// ── 1. Inspect a live TLS connection ──────────────────────────
function inspectTLS(hostname, port = 443) {
  return new Promise((resolve, reject) => {
    const socket = tls.connect(
      { host: hostname, port, servername: hostname },
      () => {
        const cert   = socket.getPeerCertificate(true);  // true = full chain
        const cipher = socket.getCipher();

        resolve({
          protocol:       socket.getProtocol(),          // 'TLSv1.3' or 'TLSv1.2'
          cipher:         cipher.name,                   // e.g. 'TLS_AES_256_GCM_SHA384'
          group:          socket.getEphemeralKeyInfo?.()?.name, // key-exchange group, e.g. 'X25519' (client side only)
          subject:        cert.subject?.CN,              // leaf common name
          issuer:         cert.issuer?.O,                // issuing CA org
          validFrom:      cert.valid_from,
          validTo:        cert.valid_to,
          fingerprint256: cert.fingerprint256,           // SHA-256 of the DER cert
          altNames:       cert.subjectaltname,           // SANs: DNS:example.com, DNS:www.example.com
          authorized:     socket.authorized,             // false = verification failed
          authError:      socket.authorizationError,     // e.g. 'CERT_HAS_EXPIRED'
        });
        socket.destroy();
      }
    );
    socket.on('error', reject);
  });
}

// ── 2. Certificate expiry monitor ─────────────────────────────
async function checkCertExpiry(hostname, warnDays = 30) {
  const info = await inspectTLS(hostname);
  const expiresAt = new Date(info.validTo);
  const daysLeft  = Math.floor((expiresAt - Date.now()) / (86_400 * 1000));

  if (!info.authorized) {
    console.error(`FAIL [${hostname}]: ${info.authError}`);
    return { hostname, ok: false, reason: info.authError };
  }
  if (daysLeft < 0) {
    console.error(`EXPIRED [${hostname}]: expired ${-daysLeft} days ago`);
  } else if (daysLeft < warnDays) {
    console.warn(`WARN [${hostname}]: ${daysLeft} days remaining (${info.validTo})`);
  } else {
    console.log(`OK [${hostname}]: ${daysLeft} days remaining, protocol=${info.protocol}, cipher=${info.cipher}`);
  }
  return { hostname, ok: true, daysLeft, protocol: info.protocol, cipher: info.cipher };
}

// ── 3. Secure HTTPS server configuration ──────────────────────
function createSecureServer(certPath, keyPath) {
  const options = {
    cert: fs.readFileSync(certPath),
    key:  fs.readFileSync(keyPath),
    // Reject TLS 1.0 and 1.1 — both formally deprecated by RFC 8996 (2021)
    minVersion: 'TLSv1.2',
    // Node's defaults are already sensible. If you do set 'ciphers', note that any
    // TLS 1.3 names you list REPLACE the TLS 1.3 defaults — so keep all three,
    // including TLS_AES_128_GCM_SHA256 (mandatory-to-implement in RFC 8446).
    ciphers: [
      'TLS_AES_128_GCM_SHA256',         // TLS 1.3
      'TLS_AES_256_GCM_SHA384',         // TLS 1.3
      'TLS_CHACHA20_POLY1305_SHA256',   // TLS 1.3 (fast on CPUs without AES-NI)
      'ECDHE-ECDSA-AES128-GCM-SHA256',  // TLS 1.2, ECDSA cert, forward secrecy
      'ECDHE-RSA-AES128-GCM-SHA256',    // TLS 1.2, RSA cert, forward secrecy
      'ECDHE-ECDSA-AES256-GCM-SHA384',  // TLS 1.2, ECDSA cert, forward secrecy
      'ECDHE-RSA-AES256-GCM-SHA384',    // TLS 1.2, RSA cert, forward secrecy
    ].join(':'),
    honorCipherOrder: true,   // server's preference order wins (TLS 1.2 suites)
  };

  return https.createServer(options, (req, res) => {
    // Security headers every HTTPS response should include:
    res.setHeader('Strict-Transport-Security',
      'max-age=63072000; includeSubDomains; preload');   // HSTS — 2 years
    res.setHeader('X-Content-Type-Options', 'nosniff');
    res.setHeader('Content-Security-Policy', "default-src 'self'; frame-ancestors 'none'"); // frame-ancestors supersedes X-Frame-Options
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ status: 'secure' }));
  });
}

// Usage:
const info = await inspectTLS('example.com');
console.log(info.protocol, info.cipher, info.group, info.authorized); // e.g. TLSv1.3 TLS_AES_256_GCM_SHA384 X25519 true
// (group is X25519MLKEM768 when both ends support hybrid PQ — Node needs OpenSSL >= 3.5)
await checkCertExpiry('example.com'); // OK [example.com]: N days remaining, protocol=TLSv1.3, ...

